    84  /***********************************************************************/
    85  static int is_leap_year(int year) {
    86  /***********************************************************************/
    87      return ((year % 4 == 0 && year % 100 != 0) || year % 400 ==0);
    88  }
    89
    90
    91  /***********************************************************************/
    92  static int days_in_year(int year) {
    93  /***********************************************************************/
    94      return is_leap_year(year) ? 366 : 365;
    95  }
    96
    97
    98  /***********************************************************************/
    99  static double mjd_to_mjd(double mjd) {
   100  /***********************************************************************
   101      Modified julian date no-op function.
   102
   103      The Julian date is defined as (fractional) days since midnight
   104      on 16th of November in 1858.
   105  ************************************************************************/
   106      return mjd;
   107  }
   108
   109
   110  /***********************************************************************/
   111  static double decimalyear_to_mjd(double decimalyear) {
   112  /***********************************************************************
   113      Epoch of modified julian date is 1858-11-16 00:00
   114  ************************************************************************/
   115      int year = (int)floor(decimalyear);
   116      double fractional_year = decimalyear - year;
   117      double mjd = (year - 1859)*365 + 14 + 31;
   118      mjd += fractional_year*days_in_year(year);
   119
   120      /* take care of leap days */
   121      year--;
   122      for (; year > 1858; year--)
   123          if (is_leap_year(year))
   124              mjd++;
   125
   126      return mjd;
   127  }
   128
   129
   130  /***********************************************************************/
   131  static double mjd_to_decimalyear(double mjd) {
   132  /***********************************************************************
   133      Epoch of modified julian date is 1858-11-16 00:00
   134  ************************************************************************/
   135      double decimalyear = mjd;
   136      double mjd_iter = 14 + 31;
   137      int year = 1859;
   138
   139      /* a smarter brain than mine could probably to do this more elegantly
   140         - I'll just brute-force my way out of this... */
   141      for (; mjd >= mjd_iter; year++) {
   142          mjd_iter += days_in_year(year);
   143      }
   144      year--;
   145      mjd_iter -= days_in_year(year);
   146
   147      decimalyear = year + (mjd-mjd_iter)/days_in_year(year);
   148      return decimalyear;
   149  }
