   184  struct pj_opaque_unitconvert {
   185      int     t_in_id;    /* time unit id for the time input unit   */
   186      int     t_out_id;   /* time unit id for the time output unit  */
   187      int     xy_in_id;   /* unit id for the horizontal input unit  */
   188      int     xy_out_id;  /* unit id for the horizontal output unit */
   189      int     z_in_id;    /* unit id for the vertical input unit    */
   190      int     z_out_id;   /* unit id for the vertical output unit   */
   191  };
