   283  /***********************************************************************/
   284  static PJ_OBS forward_obs(PJ_OBS obs, PJ *P) {
   285  /************************************************************************
   286      Forward conversion of time units
   287  ************************************************************************/
   288      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   289      PJ_OBS out;
   290
   291      /* delegate unit conversion of physical dimensions to the 3D function */
   292      out.coo.xyz = forward_3d(obs.coo.lpz, P);
   293
   294      if (Q->t_in_id >= 0)
   295          out.coo.xyzt.t = time_units[Q->t_in_id].t_in( obs.coo.xyzt.t );
   296      if (Q->t_out_id >= 0)
   297          out.coo.xyzt.t = time_units[Q->t_out_id].t_out( out.coo.xyzt.t );
   298
   299      return out;
   300  }
   301
   302
   303  /***********************************************************************/
   304  static PJ_OBS reverse_obs(PJ_OBS obs, PJ *P) {
   305  /************************************************************************
   306      Reverse conversion of time units
   307  ************************************************************************/
   308      struct pj_opaque_unitconvert *Q = (struct pj_opaque_unitconvert *) P->opaque;
   309      PJ_OBS out;
   310
   311      /* delegate unit conversion of physical dimensions to the 3D function */
   312      out.coo.lpz = reverse_3d(obs.coo.xyz, P);
   313
   314      if (Q->t_in_id >= 0)
   315          out.coo.xyzt.t = time_units[Q->t_out_id].t_in( obs.coo.xyzt.t );
   316      if (Q->t_out_id >= 0)
   317          out.coo.xyzt.t = time_units[Q->t_in_id].t_out( out.coo.xyzt.t );
   318
   319      return out;
   320  }
