   323  /***********************************************************************/
   324  PJ *PROJECTION(unitconvert) {
   325  /***********************************************************************/
   326      struct pj_opaque_unitconvert *Q = pj_calloc (1, sizeof (struct pj_opaque_unitconvert));
   327      char *s, *name;
   328      int i;
   329
   330      if (0==Q)
   331          return freeup_msg (P, ENOMEM);
   332      P->opaque = (void *) Q;
   333
   334      P->fwdobs = forward_obs;
   335      P->invobs = reverse_obs;
   336      P->fwd3d  = forward_3d;
   337      P->inv3d  = reverse_3d;
   338      P->fwd    = forward_2d;
   339      P->inv    = reverse_2d;
   340
   341      P->left  = PJ_IO_UNITS_RADIANS;
   342      P->right = PJ_IO_UNITS_RADIANS;
   343
   344      /* if no time input/output unit is specified we can skip them */
   345      Q->t_in_id = -1;
   346      Q->t_out_id = -1;
   347
   348      if ((name = pj_param (P->ctx, P->params, "sxy_in").s) != NULL) {
   349          for (i = 0; (s = pj_units[i].id) && strcmp(name, s) ; ++i);
   350
   351          if (!s) return freeup_msg(P, -8); /* unknown unit conversion id */
   352
   353          Q->xy_in_id = i;
   354          proj_log_debug(P, "xy_in unit: %s", pj_units[i].name);
   355      }
   356
   357      if ((name = pj_param (P->ctx, P->params, "sxy_out").s) != NULL) {
   358          for (i = 0; (s = pj_units[i].id) && strcmp(name, s) ; ++i);
   359
   360          if (!s) return freeup_msg(P, -8); /* unknown unit conversion id */
   361
   362          Q->xy_out_id = i;
   363          proj_log_debug(P, "xy_out unit: %s", pj_units[i].name);
   364      }
   365
   366      if ((name = pj_param (P->ctx, P->params, "sz_in").s) != NULL) {
   367          for (i = 0; (s = pj_units[i].id) && strcmp(name, s) ; ++i);
   368
   369          if (!s) return freeup_msg(P, -8); /* unknown unit conversion id */
   370
   371          Q->z_in_id = i;
   372          proj_log_debug(P, "z_in unit: %s", pj_units[i].name);
   373      }
   374
   375      if ((name = pj_param (P->ctx, P->params, "sz_out").s) != NULL) {
   376          for (i = 0; (s = pj_units[i].id) && strcmp(name, s) ; ++i);
   377
   378          if (!s) return freeup_msg(P, -8); /* unknown unit conversion id */
   379
   380          Q->z_out_id = i;
   381          proj_log_debug(P, "z_out unit: %s", pj_units[i].name);
   382      }
   383
   384
   385      if ((name = pj_param (P->ctx, P->params, "st_in").s) != NULL) {
   386          for (i = 0; (s = time_units[i].id) && strcmp(name, s) ; ++i);
   387
   388          if (!s) return freeup_msg(P, -8); /* unknown unit conversion id */
   389
   390          Q->t_in_id = i;
   391          proj_log_debug(P, "t_in unit: %s", time_units[i].name);
   392      }
   393
   394      s = 0;
   395      if ((name = pj_param (P->ctx, P->params, "st_out").s) != NULL) {
   396          for (i = 0; (s = time_units[i].id) && strcmp(name, s) ; ++i);
   397          if (!s) {
   398              return freeup_msg(P, -8); /* unknown unit conversion id */
   399          }
   400          Q->t_out_id = i;
   401          proj_log_debug(P, "t_out unit: %s", time_units[i].name);
   402      }
   403
   404      return P;
   405  }
