   413  static int test_time(char* args, double tol, double t_in, double t_exp) {
   414      PJ_OBS in, out;
   415      PJ *P = proj_create(0, args);
   416      int ret = 0;
   417
   418      if (P == 0)
   419          return 5;
   420
   421      in.coo.xyzt.t = t_in;
   422
   423      out = proj_trans_obs(P, PJ_FWD, in);
   424      if (fabs(out.coo.xyzt.t - t_exp) > tol) {
   425          proj_log_error(P, "out: %10.10g, expect: %10.10g", out.coo.xyzt.t, t_exp);
   426          ret = 1;
   427      }
   428      out = proj_trans_obs(P, PJ_INV, out);
   429      if (fabs(out.coo.xyzt.t - t_in) > tol) {
   430          proj_log_error(P, "out: %10.10g, expect: %10.10g", out.coo.xyzt.t, t_in);
